# Generates src/components/icons.data.ts from handoff/design-tokens/icons/*.svg (exact canvas icons).
import glob, json, os, re
out = {}
for f in sorted(glob.glob("handoff/design-tokens/icons/*.svg")):
    name = os.path.basename(f)[:-4]
    s = open(f).read().strip()
    m = re.match(r"<svg([^>]*)>(.*)</svg>$", s, re.S)
    attrs = dict(re.findall(r'([\w-]+)="([^"]*)"', m.group(1)))
    attrs.pop("xmlns", None)
    out[name] = {"a": attrs, "i": m.group(2)}
open("src/components/icons.data.ts", "w").write(
    "// Generated by scripts/gen-icons.py from handoff/design-tokens/icons. Do not edit.\n"
    "export const ICONS: Record<string, { a: Record<string, string>; i: string }> = "
    + json.dumps(out, indent=0) + ";\n")
print(len(out))
